<script setup lang="ts">
import { ref } from 'vue'
import { useTaskStore } from '../../stores/taskStore'
import { useResultStore } from '../../stores/resultStore'
import { useFieldLevelStore } from '../../stores/fieldLevelStore'
const props=defineProps<{rowId:string}>();defineEmits<{close:[]}>();const task=useTaskStore(),result=useResultStore(),fields=useFieldLevelStore(),error=ref('')
function edit(key:string,e:Event){const raw=(e.target as HTMLInputElement).value;const col=task.template?.columns.find(c=>c.key===key);const value=raw===''?null:col?.dataType==='number'?Number(raw):raw;if(typeof value==='number'&&!Number.isFinite(value)){error.value='请输入有效数值';return}result.edit(props.rowId,key,value);error.value=''}
</script>
<template><div class="modal-backdrop drawer-backdrop" @click.self="$emit('close')"><aside class="drawer" role="dialog" aria-modal="true" aria-label="地块详情"><div class="section-heading"><h2>地块详情与人工补充</h2><button class="secondary" @click="$emit('close')">关闭</button></div><p class="hint">{{rowId}} · 仅人工录入真实来源值；证件和确权信息不会自动生成。</p><p v-if="error" class="notice">{{error}}</p><div class="detail-fields"><label v-if="task.activeId==='full-plot'"><span>是否为确权地块（条件必填依据，人工确认）</span><select :value="result.rows.find(r=>r.rowId===rowId)?.is_confirmed===true?'yes':result.rows.find(r=>r.rowId===rowId)?.is_confirmed===false?'no':'unknown'" @change="result.edit(rowId,'is_confirmed',($event.target as HTMLSelectElement).value==='unknown'?null:($event.target as HTMLSelectElement).value==='yes')"><option value="unknown">待确认</option><option value="yes">是</option><option value="no">否</option></select><small>不根据姓名或用途推断确权状态。</small></label><label v-for="col in task.template?.columns" :key="col.key"><span>{{col.header}}</span><input :disabled="!fields.levels.find(f=>f.key===col.key)?.manualFill" :value="result.rows.find(r=>r.rowId===rowId)?.[col.key]??''" @change="edit(col.key,$event)"><small>来源：{{result.transformed.provenance[rowId]?.[col.key]?.kind || '空值'}} {{result.transformed.provenance[rowId]?.[col.key]?.sourceField || ''}}</small></label></div><details><summary>原始字段</summary><pre>{{task.plots.features.find(f=>f.properties.rowId===rowId)?.properties}}</pre></details></aside></div></template>
